#![allow(unused)]
use verus::*;

verus! {

    /// Given a vector `v` of `u64` values, with the precondition that
    /// there is at least one odd element in `v`, find and return
    /// the index of some odd element.
    ///
    /// If there are multiple odd elements, any one of their indices may
    /// be returned.
    pub fn choose_odd(v: &Vec<u64>) -> usize
        requires
            // There is at least one odd entry in v
            exists(|i: usize| i < v.len() && v[i] % 2 == 1),
        ensures
            // The returned index is in bounds and points to an odd entry
            |result: usize| result < v.len() && v[result] % 2 == 1,
    {
        let mut i: usize = 0;

        // We maintain the loop invariant that
        //   1. 0 ≤ i ≤ v.len()
        //   2. There is at least one odd element in the suffix v[i..]
        //
        // We also decrease on (v.len() - i) to ensure termination.
        while i < v.len()
            invariant i <= v.len(),
            invariant exists(|j: usize| i <= j && j < v.len() && v[j] % 2 == 1),
            decreases v.len() - i
        {
            if v[i] % 2 == 1 {
                // Found an odd element; return its index
                return i;
            }
            // Otherwise, skip this even element and continue.
            i += 1;
        }

        // By the loop invariant, reaching here would imply
        // `exists j in [i, v.len())` with v[j] odd, but i == v.len(),
        // so the suffix is empty—contradiction. Thus this point
        // is unreachable.
        unreachable!();
    }

}